{"command": "# Those are in a jump table section. Let me try objdump to get the actual function
# Or use addr2line with different options
aarch64-linux-gnu-addr2line -f -C -i -e /tmp/monosgen_dbg 0x2f4b20 0x2f4c84
echo "==="
# Try with the .so itself using debug-file-directory
aarch64-linux-gnu-objdump -d --start-address=0x2f4b20 --stop-address=0x2f4b24 /tmp/monosgen_dbg 2>/dev/null | head -10
echo "==="
# Maybe these addresses are in a data section (jump table), let's check what section they're in
aarch64-linux-gnu-readelf -S /tmp/monosgen_dbg | grep -E "\.text|\.rodata" | head -5
echo "==="
# Check which section contains 0x2f4b20
python3 << 'EOF'
import subprocess
result = subprocess.run(['aarch64-linux-gnu-readelf', '-S', '/tmp/monosgen_dbg'], capture_output=True, text=True)
for line in result.stdout.split('\n'):
    if ']' in line and ('PROGBITS' in line or 'NOTE' in line):
        parts = line.split()
        # Find section with address range containing our targets
        for i, p in enumerate(parts):
            if len(p) == 16 and all(c in '0123456789abcdef' for c in p):
                try:
                    addr = int(p, 16)
                    if i+1 < len(parts):
                        size = int(parts[i+1], 16)
                        if addr <= 0x2f4b20 < addr + size:
                            print(f"0x2f4b20 is in section: {line.strip()}")
                except:
                    pass
EOF", "description": "Investigate unresolved addresses"}

{"command": "# 0x2f4b20 and 0x2f4c84 fall in .data.rel.ro (0x2f3810 - 0x2f6c18)
# 0x2c1a40 falls in .text (starts at 0xc2480, .plt starts at 0x2ec500, so .text is 0xc2480-0x2ec500)
# Wait, 0x2c1a40 is in .text range (0xc2480 to 0x2ec500). Good.
# 0x2f4b20 is in .data.rel.ro - it's data, not code! These must be data addresses or jump table entries.

# Let me re-read the tombstone - these are PC values from backtrace, so they should be code.
# Perhaps the SGen worker thread has PC in a jump table used for computed gotos (interpreter).
# The mono interpreter uses computed goto with labels-as-values.

# For the SGen worker thread, the pc values being in .data.rel.ro strongly suggests 
# these are the interpreter's dispatch table entries. The actual function is the interpreter main loop.

# Let me resolve 0x2c1a40 properly (it's in .text):
aarch64-linux-gnu-addr2line -f -e /tmp/monosgen_dbg 0x2c1a40
echo "---"
# And check what function 0x2f4b20 might be part of by looking at nearby text
aarch64-linux-gnu-nm --defined-only /tmp/monosgen_dbg | sort | awk -v target=0x2f4b20 '
BEGIN { target_val = strtonum(target) }
{
    addr = strtonum("0x" $1)
    if (addr <= target_val) { best_addr = $1; best_name = $3 }
    if (addr > target_val) { print best_addr " " best_name " (+" target_val - strtonum("0x" best_addr) ")"; exit }
}'", "description": "Resolve addresses in code sections"}
